{
  "narrative_summary": "This result rests on how Customer Acquisition Cost feeds through to New Revenue. If that cost rises enough, more runs could support a different option. In this model, 41% of runs supported Self Serve Funnel.",
  "story_headlines": {
    "opt_selfserve": "Self Serve Funnel holds up because its modelled outcome stays strong even as acquisition cost varies.",
    "opt_paid": "Paid Acquisition would need acquisition cost to fall for more runs to support it.",
    "opt_partner": "Partner Channel would need a stronger modelled revenue outcome relative to its acquisition cost to gain runs.",
    "opt_outbound": "Outbound Sales would need its modelled outcome range to narrow and lift for more runs to support it."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 64% of variations, a moderate level based on current estimates.",
    "primary_risk": "The link from Customer Acquisition Cost to New Revenue is the main point of fragility in this result.",
    "stability_factors": [
      "Self Serve Funnel keeps a favourable modelled outcome range across most variations tested."
    ],
    "fragility_factors": [
      "The link from Customer Acquisition Cost to New Revenue could flip which option more runs support."
    ]
  },
  "readiness_rationale": "The comparison is settled enough to act on, though Customer Acquisition Cost is the one factor worth confirming before committing budget.",
  "evidence_enhancements": {
    "fac_cac": {
      "specific_action": "Pull actual blended acquisition cost from the last full quarter of spend data rather than relying on the modelled estimate.",
      "rationale": "This factor has the highest value evidence you could gather for this decision.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the current acquisition cost yourself before looking at the actual figure."
    }
  },
  "scenario_contexts": {
    "edge_cac_growth": {
      "trigger_description": "If Customer Acquisition Cost rises well beyond current levels...",
      "consequence": "...then the most runs would support Paid Acquisition rather than Self Serve Funnel."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_cac",
